class Counter
    private define value as integer;

    method constructor()
        this.value <- 0;
    endMethod

    public method Increment()
        this.value <- this.value + 1;
    endMethod

    public method Value() as integer
        return this.value;
    endMethod
endClass

algorithm RunCounter
    define times as integer;
    define i as integer;
    define counter as Counter;
    read times;
    counter <- new Counter();
    for i <- 1 to times step 1 do
        counter.Increment();
    endFor
    write counter.Value();
endAlgorithm
